CREATE    PROCEDURE [synapse_fo].[usp_Populate_LEDGERTRANS_RICS]

@LOADTYPE bit = 0

AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-19 09:40
	Description: Stored procedure to populate LEDGERTRANS_RICS BI table
*/
BEGIN



IF @LOADTYPE = 1 --Full Load = 1, Incremental Load = 0
BEGIN 
	TRUNCATE TABLE [synapse_fo].[LEDGERTRANS_RICS]
END

	--BEGIN TRY

	--	BEGIN TRANSACTION
	DROP TABLE IF EXISTS #VCH
	SELECT 
	 VOUCHER
	,COUNT(DISTINCT ACCOUNTNUM) AS 'Account_Count'
	INTO #VCH
	FROM [synapse_fo].[CUSTTRANS_RICS] CT
	GROUP BY CT.VOUCHER
	HAVING COUNT(DISTINCT ACCOUNTNUM) > 1

	DROP TABLE IF EXISTS #CT
	SELECT 
	 VOUCHER
	,MAX(ACCOUNTNUM) AS ACCOUNTNUM
	INTO #CT
	FROM synapse_fo.CUSTTRANS CT
	WHERE NOT EXISTS (
		SELECT VCH.VOUCHER
		FROM #VCH VCH
		WHERE VCH.VOUCHER = CT.VOUCHER
		)
	GROUP BY VOUCHER

	DROP TABLE IF EXISTS #CTM
	SELECT 
	 ACCOUNTNUM
	,VOUCHER
	,AMOUNTCUR
	,RECID
	,ROW_NUMBER() OVER (PARTITION BY CT.VOUCHER, CT.AMOUNTCUR ORDER BY RECID) AS Row_Num
	INTO #CTM
	FROM synapse_fo.CUSTTRANS CT
	WHERE EXISTS (
		SELECT VCH.VOUCHER
		FROM #VCH VCH
		WHERE VCH.VOUCHER = CT.VOUCHER
		)


--Get Supplier Vouchers
	DROP TABLE IF EXISTS #SUPPVCH
	SELECT 
	 VT.VOUCHER
	 ,VT.DATAAREAID
	,MAX(VT.ACCOUNTNUM) AS 'Supplier Account No'
	INTO #SUPPVCH
	FROM [synapse_fo].[VENDTRANS] VT
	GROUP BY VT.VOUCHER, VT.DATAAREAID




			--Load target table
			INSERT INTO [synapse_fo].[LEDGERTRANS_RICS]
			(
				[RECID],
				[GENERALJOURNALENTRY],
				[ACCOUNTDISPLAYVALUE],
				--[LEDGERACCOUNT],
				[JOURNALNUMBER],
				[SUBLEDGERVOUCHER],
				[ACCOUNTINGDATE],
				--[POSTINGLAYER],
				[TRANSACTIONCURRENCYCODE],
				[TRANSACTIONCURRENCYAMOUNT],
				[ACCOUNTINGCURRENCYAMOUNT],
				[REPORTINGCURRENCYAMOUNT],
				--[DESCRIPTION],
				--[QUANTITY],
				[POSTINGTYPE],
				[JOURNALCATEGORY],
				[ISCORRECTION],
				[ISCREDIT],
				[ACKNOWLEDGEMENTDATE],
				[DOCUMENTDATE],
				[DOCUMENTNUMBER],
				--[LEDGERNAME],
				[MAINACCOUNT],
				[TEXT],
				--[ALLOCATIONLEVEL],
				[PAYMENTREFERENCE],
				[REASONREF],
				[DATAAREAID],
				[RICSCOSTCENTER],
				[RICSCAMPAIGNYEAR],
				--[RICSCHANNEL],
				[RICSCOUNTRY],
				--[RICSCUSTOMER],
				--[RICSENTITY],
				[RICSFIXEDASSETGROUP],
				--[RICSFUNCTION],
				[RICSINTERCOMPANY],
				[RICSINTERIMREPORTINGENTITY],
				--[RICSLOCATION],
				--[RICSNEW_RENEWAL],
				[RICSPRODUCTCODE],
				[RICSPRODUCTGROUP],
				[RICSPROJECT],
				[TB_Category_Code],
				[CREATEDBY1],
				[CREATEDDATETIME1],
				[ACCOUNTNUM],
				[SUPPLIER_ACCOUNTNUM]
			)
			SELECT
				T1.[RECID],
				T1.[GENERALJOURNALENTRY],
				T1.[ACCOUNTDISPLAYVALUE],
				--[LEDGERACCOUNT],
				T1.[JOURNALNUMBER],
				T1.[SUBLEDGERVOUCHER],
				T1.[ACCOUNTINGDATE],
				--[POSTINGLAYER],
				T1.[TRANSACTIONCURRENCYCODE],
				T1.[TRANSACTIONCURRENCYAMOUNT],
				T1.[ACCOUNTINGCURRENCYAMOUNT],
				T1.[REPORTINGCURRENCYAMOUNT],
				--[DESCRIPTION],
				--[QUANTITY],
				T1.[POSTINGTYPE],
				T1.[JOURNALCATEGORY],
				T1.[ISCORRECTION],
				T1.[ISCREDIT],
				T1.[ACKNOWLEDGEMENTDATE],
				T1.[DOCUMENTDATE],
				T1.[DOCUMENTNUMBER],
				--[LEDGERNAME],
				T1.[MAINACCOUNT],
				T1.[TEXT],
				--[ALLOCATIONLEVEL],
				T1.[PAYMENTREFERENCE],
				T1.[REASONREF],
				T1.[DATAAREAID],
				T1.[RICSCOSTCENTER],
				T1.[RICSCAMPAIGNYEAR],
				--[RICSCHANNEL],
				T1.[RICSCOUNTRY],
				--[RICSCUSTOMER],
				--[RICSENTITY],
				T1.[RICSFIXEDASSETGROUP],
				--[RICSFUNCTION],
				T1.[RICSINTERCOMPANY],
				T1.[RICSINTERIMREPORTINGENTITY],
				--[RICSLOCATION],
				--[RICSNEW_RENEWAL],
				T1.[RICSPRODUCTCODE],
				T1.[RICSPRODUCTGROUP],
				T1.[RICSPROJECT],
				T1.[TB_Category_Code],
				T1.[CREATEDBY1],
				T1.[CREATEDDATETIME1],
				COALESCE(CT.ACCOUNTNUM, CTM.ACCOUNTNUM) AS ACCOUNTNUM,
				SUPP.[Supplier Account No]
			FROM [synapse_fo].[vwLedgerTrans] T1
			LEFT JOIN [synapse_fo].[LEDGERTRANS_RICS] T2
				ON T1.[RECID] = T2.[RECID]
			LEFT JOIN #CT CT
				ON T1.SUBLEDGERVOUCHER = CT.VOUCHER
			LEFT JOIN #CTM CTM
				ON T1.SUBLEDGERVOUCHER = CTM.VOUCHER
				AND T1.TRANSACTIONCURRENCYAMOUNT = CTM.AMOUNTCUR
				AND T1.Row_Num = CTM.Row_Num
			LEFT JOIN #SUPPVCH supp
				ON T1.SUBLEDGERVOUCHER = supp.VOUCHER
				AND T1.DATAAREAID = supp.DATAAREAID
			WHERE T2.[RECID] IS NULL

/*		
		COMMIT TRANSACTION

	END TRY
	BEGIN CATCH
		DECLARE @Error_Message NVARCHAR(4000)
		SET @Error_Message = 'synapse_fo.usp_Populate_LEDGERTRANS_RICS procedure failed: ' + ERROR_MESSAGE()
		

		-- Transaction uncommittable
		IF (XACT_STATE()) = -1
		  ROLLBACK TRANSACTION
 
		-- Transaction committable
		IF (XACT_STATE()) = 1
		  COMMIT TRANSACTION

		--Fail the procedure
		RAISERROR (15600, 20, -1, @Error_Message);

	END CATCH
*/
END
